        id: newID(),
        title: seed.title,
        endpoint: seed.endpoint,
        kind: seed.kind,
        topic: seed.topic,
        enabled: seed.enabled,
        isBuiltin: true,
        sortOrder: index,
        lastFetched: 0,
    }));
}

